import sys

data = sys.stdin.read().split()
n = int(data[0])
log = [(data[1 + 3 * i], data[2 + 3 * i], int(data[3 + 3 * i])) for i in range(n)]
riders = sorted(set(r for r, _, _ in log))
seqs = {}
for r in riders:
    seqs[r] = [c for (t, c) in sorted((t, c) for rr, c, t in log if rr == r)]

def has(cs, tr):
    for i in range(len(cs) - 2):
        if (cs[i], cs[i + 1], cs[i + 2]) == tr:
            return True
    return False

cands = set()
for r in riders:
    cs = seqs[r]
    for i in range(len(cs) - 2):
        cands.add((cs[i], cs[i + 1], cs[i + 2]))
res = []
for tr in cands:
    res.append((-sum(1 for r in riders if has(seqs[r], tr)), tr))
res.sort()
print(len(res))
for k, tr in res:
    print(tr[0], tr[1], tr[2], -k)

